export function RoutesView({storageScope,workspaceId,workspaceRole,data,query,onAdd,onRemove,onStatus,owner,setOwner,workspace,setWorkspace,setNotice,setDark,onLogout,platformRole}:{storageScope:string;workspaceId:string;workspaceRole:'OWNER'|'ADMIN'|'MANAGER'|'MEMBER'|'VIEWER';data:Record<Dataset,RecordItem[]>;query:string;onAdd:(k:Dataset)=>void;onRemove:(k:Dataset,id:string)=>void;onStatus:(k:Dataset,id:string,s:string)=>void;owner:string;setOwner:(v:string)=>void;workspace:string;setWorkspace:(v:string)=>void;setNotice:(v:string)=>void;setDark:(v:boolean)=>void;onLogout:()=>void;platformRole?:string}){
 const path=useLocation().pathname;
 if(path==='/')return <HomePage data={data} owner={owner} onAdd={onAdd} workspaceId={workspaceId}/>;
 if(path==='/dashboard')return <Dashboard data={data} workspaceId={workspaceId}/>;
 if(path==='/ai')return <ApiAI workspaceId={workspaceId}/>;
 if(path==='/analytics')return <ApiReports workspaceId={workspaceId}/>;
 if(path==='/files')return <ApiFiles workspaceId={workspaceId}/>;
 if(path==='/billing')return <ApiBilling workspaceId={workspaceId} workspaceRole={workspaceRole}/>;
 if(path==='/calendar')return <ApiCalendar workspaceId={workspaceId}/>;if(path==='/notifications')return <ApiNotifications workspaceId={workspaceId}/>;
 if(path==='/admin')return ['ADMIN','SUPER_ADMIN','SUPPORT'].includes(platformRole||'')?<AdminPage role={platformRole||'USER'}/>:<div className="panel">Platform administrator access is required.</div>;
 if(path==='/settings')return <SettingsPage storageScope={storageScope} workspaceId={workspaceId} workspaceRole={workspaceRole} owner={owner} setOwner={setOwner} workspace={workspace} setWorkspace={setWorkspace} setNotice={setNotice} setDark={setDark} onLogout={onLogout}/>;
 const match:Record<string,Dataset>={'/projects':'projects','/tasks':'tasks','/customers':'customers','/invoices':'invoices'};
 const kind=match[path];if(kind==='projects')return <ApiProjects workspaceId={workspaceId} query={query}/>;if(kind==='tasks')return <ApiTasks workspaceId={workspaceId} query={query}/>;if(kind==='customers')return <ApiCustomers workspaceId={workspaceId} query={query}/>;if(kind==='invoices')return <ApiInvoices workspaceId={workspaceId} query={query}/>;if(kind)return <DataPage kind={kind} items={data[kind]} query={query} onAdd={()=>onAdd(kind)} onRemove={id=>onRemove(kind,id)} onStatus={(id,s)=>onStatus(kind,id,s)}/>;
 return <HomePage data={data} owner={owner} onAdd={onAdd} workspaceId={workspaceId}/>;
}
function Heading({eyebrow,title,desc,action}:{eyebrow:string;title:string;desc:string;action?:ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{desc}</p></div>{action}</div>}

function HomePage({data,owner,onAdd,workspaceId}:{data:Record<Dataset,RecordItem[]>;owner:string;onAdd:(k:Dataset)=>void;workspaceId:string}){
 const navigate=useNavigate();
 const [overview,setOverview]=useState<DashboardOverview|null>(null),[overviewError,setOverviewError]=useState(''),[overviewLoading,setOverviewLoading]=useState(true);useEffect(()=>{let active=true;setOverview(null);setOverviewError('');setOverviewLoading(true);dashboardService.overview(workspaceId).then(r=>{if(active)setOverview(r)}).catch(e=>{if(active)setOverviewError(e instanceof Error?e.message:'Dashboard data could not be loaded.')}).finally(()=>{if(active)setOverviewLoading(false)});return()=>{active=false}},[workspaceId]);
 const [liveTasks,setLiveTasks]=useState<TaskRecord[]>([]),[taskError,setTaskError]=useState(''),[tasksLoading,setTasksLoading]=useState(true);useEffect(()=>{let active=true;setLiveTasks([]);setTaskError('');setTasksLoading(true);taskService.list(workspaceId).then(r=>{if(active)setLiveTasks(r.tasks.filter(t=>t.status!=='DONE'))}).catch(e=>{if(active)setTaskError(e instanceof Error?e.message:'Tasks could not be loaded.')}).finally(()=>{if(active)setTasksLoading(false)});return()=>{active=false}},[workspaceId]);const tasks=liveTasks,revenue=overview?.kpis.revenue??null,revenueDisplay=overview?.kpis.revenue===null?'Multiple currencies':revenue===null?'—':money(revenue,overview?.revenueByCurrency?.[0]?.currency||'USD');
 return <><Heading eyebrow="YOUR WORKSPACE" title={`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}${owner?', '+owner.split(' ')[0]:''}.`} desc={`${dateLabel()} · Here's your workspace at a glance.`} action={<button className="btn primary" onClick={()=>navigate('/tasks')}><Plus size={16}/> New task</button>}/>
 {(overviewError||taskError)&&<div className="error-note">Live workspace data could not be fully loaded. {overviewError} {taskError}</div>}<div className="quick-grid"><Quick label="Projects" value={overview?.kpis.activeProjects??'—'} icon={<FolderKanban/>} hint="Created in this workspace"/><Quick label="Open tasks" value={overview?.kpis.openTasks??'—'} icon={<CheckSquare/>} hint="Not marked complete"/><Quick label="Customers" value={overview?.kpis.newCustomers??'—'} icon={<Users/>} hint="Saved contacts"/><Quick label="Paid invoices" value={revenueDisplay} icon={<Wallet/>} hint={`${overview?.kpis.paidInvoices??'—'} marked paid`}/></div>
 <div className="content-grid home-grid"><section className="panel"><PanelHead title="Recent projects" sub="Your latest work" href="/projects"/>{overviewLoading?<div className="route-loading">Loading projects…</div>:overviewError?<div className="empty"><b>Projects unavailable</b><p>Could not verify the project list from the server.</p></div>:(overview?.recentProjects||[]).length?(overview?.recentProjects||[]).map(p=><div className="list-row" key={p.id}><span className="list-icon purple"><FolderKanban size={16}/></span><span className="row-main"><b>{p.name}</b><small>{'description' in p?(p as any).description||'No description added':p.progress+'% complete'}</small></span><Status value={p.status}/></div>):<Empty title="No projects yet" desc="Create a project to start organizing your work." action="Add project" onClick={()=>navigate('/projects')}/>}</section>
 <section className="panel"><PanelHead title="Tasks to focus on" sub="Your next actions" href="/tasks"/>{tasksLoading?<div className="route-loading">Loading tasks…</div>:taskError?<div className="empty"><b>Tasks unavailable</b><p>Could not verify the task list from the server.</p></div>:tasks.slice(0,4).length?tasks.slice(0,4).map(t=><div className="list-row" key={t.id}><span className="list-icon green"><CheckSquare size={16}/></span><span className="row-main"><b>{t.title}</b><small>{t.dueDate?`Due ${new Date(t.dueDate).toLocaleDateString()}`:'No due date'}</small></span><Status value={t.status.replaceAll('_',' ')}/></div>):<Empty title="You're clear" desc="There are no open tasks. Add one when you're ready." action="Create task" onClick={()=>navigate('/tasks')}/>}</section>
 <section className="panel"><PanelHead title="Quick actions" sub="Create something new"/><div className="action-grid">{(['projects','tasks','customers','invoices'] as Dataset[]).map(k=><button className="action-tile" key={k} onClick={()=>navigate('/'+k)}><Plus size={16}/><span>New {k.slice(0,-1)}</span><ArrowUpRight size={14}/></button>)}</div></section>
 <section className="panel"><PanelHead title="Workspace status" sub="A transparent view of your data"/><div className="status-info"><span className="status-orb"/><div><b>Workspace data storage</b><small>Projects, tasks, customers, invoices and calendar events are stored in this workspace through the FlowDesk API.</small></div></div><div className="status-info"><span className="status-orb muted"/><div><b>AI connection</b><small>AI provider credentials are configured securely on the backend. Open the AI Assistant to check connectivity.</small></div></div></section></div></>;
}
function Quick({label,value,icon,hint}:{label:string;value:string|number;icon:ReactNode;hint:string}){return <div className="quick-card"><div className="quick-top"><span>{label}</span><i>{icon}</i></div><strong>{value}</strong><small>{hint}</small></div>}
function PanelHead({title,sub,href}:{title:string;sub:string;href?:string}){return <div className="panel-head"><div><h3>{title}</h3><p>{sub}</p></div>{href&&<NavLink to={href}>View all <ArrowUpRight size={13}/></NavLink>}</div>}
function Empty({title,desc,action,onClick}:{title:string;desc:string;action:string;onClick:()=>void}){return <div className="empty"><span className="empty-symbol"><Activity size={19}/></span><b>{title}</b><p>{desc}</p><button className="btn secondary small" onClick={onClick}><Plus size={14}/>{action}</button></div>}
function Status({value}:{value:string}){return <span className={'status '+value.toLowerCase().replace(/\s/g,'-')}>{value}</span>}
function Dashboard({data,workspaceId}:{data:Record<Dataset,RecordItem[]>;workspaceId:string}){
 const [remote,setRemote]=useState<DashboardOverview|null>(null),[range,setRange]=useState('month'),[error,setError]=useState('');
 useEffect(()=>{let active=true;setRemote(null);setError('');const now=new Date();const from=new Date(now);if(range==='week')from.setDate(now.getDate()-7);else if(range==='year')from.setFullYear(now.getFullYear()-1);else from.setMonth(now.getMonth()-1);dashboardService.overview(workspaceId,from.toISOString(),now.toISOString()).then(r=>{if(active){setRemote(r);setError('')}}).catch(e=>{if(active)setError(e instanceof Error?e.message:'Dashboard data could not be loaded.')});return()=>{active=false}},[workspaceId,range]);
 const paidCount=remote?.kpis.paidInvoices??0;
 const revenue=remote?.kpis.revenue??0,open=remote?.kpis.openTasks??0,active=remote?.kpis.activeProjects??0;
 const months=useMemo(()=>{if(!remote||!remote.revenueSeries.length)return [];const grouped=new Map<string,number>();remote.revenueSeries.forEach(x=>{const key=x.date.slice(0,7);grouped.set(key,(grouped.get(key)||0)+x.amount)});return [...grouped.entries()].sort(([a],[b])=>a.localeCompare(b)).slice(-7).map(([key,income])=>({key,label:new Date(`${key}-01T00:00:00`).toLocaleString(undefined,{month:'short'}),income,expense:0}));},[remote]);
 const revenueCurrency=remote?.revenueByCurrency?.[0]?.currency||'USD';
 const categories:[string,number][]=[['Projects',remote?.kpis.activeProjects??0],['Tasks',remote?remote.kpis.openTasks+remote.kpis.completedTasks:0],['Customers',remote?.kpis.newCustomers??0],['Invoices',remote?remote.kpis.paidInvoices+remote.kpis.outstandingInvoices:0]];
 const totalRecords=categories.reduce((sum,x)=>sum+x[1],0);
 const taskStatuses=remote?{ 'To do':remote.taskProgress.TODO,'In progress':remote.taskProgress.IN_PROGRESS,'In review':remote.taskProgress.IN_REVIEW,'Done':remote.taskProgress.DONE}:null;
 const statusCounts=['To do','In progress','In review','Done'].map(name=>({name,count:taskStatuses?taskStatuses[name as keyof typeof taskStatuses]:0}));
 const recent=remote?.recentActivity?.map(a=>({id:a.id,name:`${a.project.name} · ${a.action.replaceAll('_',' ')}`,status:'Updated',createdAt:a.createdAt}))||[];
 const max=Math.max(1,...months.map(m=>m.income));
 return <div className="reference-dashboard">
  <div className="dash-topline"><div><div className="eyebrow">FLOWDESK / WORKSPACE</div><h1>Dashboard Overview</h1><p>Workspace metrics calculated from saved business records.</p></div><div className="dash-tools"><select aria-label="Dashboard date range" value={range} onChange={e=>setRange(e.target.value)}><option value="week">Last 7 days</option><option value="month">Last 30 days</option><option value="year">Last 12 months</option></select><NavLink to="/ai" className="btn primary"><Sparkles size={15}/> Ask FlowDesk AI</NavLink></div></div>
  {error&&<div className="error-note">Dashboard data is unavailable from the server: {error}</div>}
  <div className="dash-kpis"><div className="dash-kpi"><span>Workspace activity</span><strong>{remote?totalRecords:'—'}</strong><small>{totalRecords===1?'record':'records'} in selected workspace</small><i><Activity/></i></div><div className="dash-kpi"><span>Total revenue</span><strong>{!remote?'—':remote.kpis.revenue===null?'Multiple currencies':money(revenue,revenueCurrency)}</strong><small>{paidCount} paid {paidCount===1?'invoice':'invoices'}</small><i><Wallet/></i></div><div className="dash-kpi"><span>Open tasks</span><strong>{remote?open:'—'}</strong><small>{active} active projects</small><i><CheckSquare/></i></div></div>
  <div className="dash-main-grid"><section className="dash-card dash-sales"><div className="dash-card-head"><div><h3>Revenue performance</h3><p>Paid invoices in selected date range · actual data only</p></div><span className="dash-pill">{remote?'Server data':'Waiting for server'}</span></div>{months.some(m=>m.income>0)?<div className="dash-chart">{months.map(m=><div className="dash-bar-group" key={m.key}><div className="dash-bar" style={{height:`${Math.max(4,m.income/max*100)}%`}} title={`${m.label}: ${money(m.income,revenueCurrency)}`}/><small>{m.label}</small></div>)}</div>:<div className="dash-empty"><Wallet size={25}/><b>No revenue recorded yet</b><span>Paid invoices will populate this chart when financial records are connected.</span><NavLink to="/invoices">Open invoices <ArrowUpRight size={13}/></NavLink></div>}</section>
  <section className="dash-card dash-side"><div className="dash-card-head"><div><h3>Workspace snapshot</h3><p>Records in selected workspace</p></div></div>{categories.map(([label,count])=><div className="dash-stat-row" key={label}><span>{label}</span><b>{count}</b></div>)}<div className="dash-card-head mini-head"><div><h3>Task progress</h3><p>By current status</p></div></div>{statusCounts.map(s=><div className="dash-progress" key={s.name}><div><span>{s.name}</span><b>{s.count}</b></div><i><em style={{width:`${(remote?remote.kpis.openTasks+remote.kpis.completedTasks:0)?s.count/(remote?remote.kpis.openTasks+remote.kpis.completedTasks:1)*100:0}%`}}/></i></div>)}</section></div>
  <div className="dash-bottom-grid"><section className="dash-card dash-imports"><div className="dash-card-head"><div><h3>Record distribution</h3><p>Workspace record composition</p></div></div><div className="distribution"><div className="donut" style={{background:`conic-gradient(var(--accent) ${totalRecords?categories[0][1]/totalRecords*100:0}%, #f2b36c 0 ${totalRecords?(categories[0][1]+categories[1][1])/totalRecords*100:0}%, #8eb8a5 0 ${totalRecords?(categories[0][1]+categories[1][1]+categories[2][1])/totalRecords*100:0}%, #d8dce5 0)`}}><span>{totalRecords}<small>records</small></span></div><div className="distribution-legend">{categories.map(([name,count],i)=><div key={name}><i className={`legend-dot d${i}`}/><span>{name}</span><b>{count}</b></div>)}</div></div></section>
  <section className="dash-card dash-category"><div className="dash-card-head"><div><h3>Recent activity</h3><p>Latest project updates</p></div><span className="dash-pill">{recent.length} items</span></div>{recent.length?recent.map(item=><div className="dash-activity" key={item.id}><span className="activity-dot"/><div><b>{item.name}</b><small>{new Date(item.createdAt).toLocaleDateString()} · {item.status}</small></div></div>):<div className="dash-empty compact"><b>No activity yet</b><span>Workspace activity will appear as you create records.</span></div>}</section>
  <section className="dash-card dash-growth"><div className="dash-card-head"><div><h3>FlowDesk AI</h3><p>Your workspace assistant</p></div><span className="ai-orb"><Sparkles size={17}/></span></div><p className="ai-card-copy">Ask questions about workspace data. Answers require your configured AI service.</p><NavLink to="/ai" className="btn primary full">Open AI Assistant <ArrowUpRight size={14}/></NavLink><div className="ai-card-foot">Context available: {totalRecords} records</div></section></div>
 </div>;
}

function ApiProjects({workspaceId,query}:{workspaceId:string;query:string}){
 const [projects,setProjects]=useState<Project[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[showForm,setShowForm]=useState(false),[selected,setSelected]=useState<Project|null>(null),[name,setName]=useState(''),[description,setDescription]=useState(''),[priority,setPriority]=useState<Project['priority']>('MEDIUM'),[dueDate,setDueDate]=useState(''),[budget,setBudget]=useState(''),[currency,setCurrency]=useState('USD'),[milestone,setMilestone]=useState(''),[members,setMembers]=useState<Array<{user:{id:string;name:string}}> >([]),[assigneeId,setAssigneeId]=useState(''),[editing,setEditing]=useState(false),[editName,setEditName]=useState(''),[editDescription,setEditDescription]=useState(''),[editDueDate,setEditDueDate]=useState(''),[editBudget,setEditBudget]=useState(''),[editProgress,setEditProgress]=useState(0),[editPriority,setEditPriority]=useState<Project['priority']>('MEDIUM'),[editAssigneeId,setEditAssigneeId]=useState('');
 const refresh=async()=>{setLoading(true);try{const r=await projectService.list(workspaceId,query);setProjects(r.projects);setError('')}catch(e){setError(e instanceof Error?e.message:'Projects could not be loaded.')}finally{setLoading(false)}};
 useEffect(()=>{void refresh();workspaceService.members(workspaceId).then(r=>setMembers(r.members)).catch(()=>{})},[workspaceId,query]);
 const create=async(e:FormEvent)=>{e.preventDefault();try{await projectService.create(workspaceId,{name,description,priority,dueDate:dueDate||undefined,budget:budget?Number(budget):undefined,currency,assigneeId:assigneeId||undefined});setName('');setDescription('');setDueDate('');setBudget('');setAssigneeId('');setShowForm(false);await refresh()}catch(err){setError(err instanceof Error?err.message:'Project could not be created.')}};
 const changeStatus=async(project:Project,status:Project['status'])=>{try{await projectService.update(workspaceId,project.id,{status});await refresh();if(selected?.id===project.id)setSelected({...project,status})}catch(e){setError(e instanceof Error?e.message:'Project status could not be updated.')}};
 const open=async(project:Project)=>{try{const r=await projectService.detail(workspaceId,project.id);const detail=r.project as Project;setSelected(detail);setEditName(detail.name);setEditDescription(detail.description||'');setEditDueDate(detail.dueDate?detail.dueDate.slice(0,10):'');setEditBudget(detail.budget||'');setEditProgress(detail.progress);setEditPriority(detail.priority);setEditAssigneeId(detail.assigneeId||'');setEditing(false)}catch(e){setError(e instanceof Error?e.message:'Project details could not be loaded.')}};
 const addMilestone=async(e:FormEvent)=>{e.preventDefault();if(!selected||!milestone.trim())return;try{await projectService.addMilestone(workspaceId,selected.id,{title:milestone.trim()});setMilestone('');await open(selected)}catch(e){setError(e instanceof Error?e.message:'Milestone could not be created.')}};
 const saveEdit=async(e:FormEvent)=>{e.preventDefault();if(!selected)return;try{await projectService.update(workspaceId,selected.id,{name:editName,description:editDescription,dueDate:editDueDate||null,budget:editBudget?Number(editBudget):null,progress:editProgress,priority:editPriority,assigneeId:editAssigneeId||null});await refresh();await open(selected)}catch(e){setError(e instanceof Error?e.message:'Project changes could not be saved.')}};
 const completeMilestone=async(milestoneId:string)=>{if(!selected)return;try{await projectService.completeMilestone(workspaceId,selected.id,milestoneId);await open(selected)}catch(e){setError(e instanceof Error?e.message:'Milestone could not be completed.')}};
 const archive=async(project:Project)=>{if(!confirm(`Archive “${project.name}”?`))return;try{await projectService.archive(workspaceId,project.id);setSelected(null);await refresh()}catch(e){setError(e instanceof Error?e.message:'Project could not be archived.')}};
 const remove=async(project:Project)=>{if(!confirm(`Permanently delete “${project.name}”? This cannot be undone.`))return;try{await projectService.remove(workspaceId,project.id);setSelected(null);await refresh()}catch(e){setError(e instanceof Error?e.message:'Project could not be deleted.')}};
 const columns:[string,Project['status'][]][]=[['Planning',['PLANNING']],['In progress',['ACTIVE','ON_HOLD']],['Completed',['COMPLETED']]];
 return <><Heading eyebrow="WORKSPACE / PROJECTS" title="Projects" desc="Plan, organize and track delivery across this workspace." action={<button className="btn primary" onClick={()=>setShowForm(v=>!v)}><Plus size={16}/> New project</button>}/>{error&&<div className="error-note">{error}</div>}{loading?<div className="panel">Loading workspace projects…</div>:<div className="board-columns">{columns.map(([label,statuses])=><section className="board-column" key={label}><div className="column-head"><span className="column-dot"/><b>{label}</b><i>{projects.filter(p=>statuses.includes(p.status)).length}</i></div>{projects.filter(p=>statuses.includes(p.status)).map(p=><article className="board-card" key={p.id}><div className="card-menu"><Status value={p.status.replace('_',' ')}/><button className="icon" onClick={()=>void open(p)} title="Project details"><MoreHorizontal size={15}/></button></div><button className="project-title-button" onClick={()=>void open(p)}><b>{p.name}</b></button><p>{p.description||'No description added.'}</p><small>{p.priority} priority · {p.dueDate?`Due ${new Date(p.dueDate).toLocaleDateString()}`:'No deadline'}</small><div className="project-progress"><i><em style={{width:`${p.progress}%`}}/></i><small>{p.progress}%</small></div><select value={p.status} onChange={e=>void changeStatus(p,e.target.value as Project['status'])}><option value="PLANNING">Planning</option><option value="ACTIVE">In progress</option><option value="ON_HOLD">On hold</option><option value="COMPLETED">Completed</option></select></article>)}</section>)}</div>}{!loading&&projects.length===0&&<div className="panel board-empty"><Empty title="No projects yet" desc="Create your first project. It will be saved to the active workspace on the FlowDesk server." action="Create project" onClick={()=>setShowForm(true)}/></div>}
 {showForm&&<div className="modal-backdrop"><form className="record-modal" onSubmit={create}><div className="modal-head"><div><div className="eyebrow">NEW WORKSPACE RECORD</div><h2>Create project</h2></div><button type="button" className="icon" onClick={()=>setShowForm(false)}><X/></button></div><label>Project name<input required minLength={2} maxLength={120} value={name} onChange={e=>setName(e.target.value)}/></label><label>Description<textarea rows={3} maxLength={5000} value={description} onChange={e=>setDescription(e.target.value)}/></label><div className="form-row"><label>Priority<select value={priority} onChange={e=>setPriority(e.target.value as Project['priority'])}><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>URGENT</option></select></label><label>Due date<input type="date" value={dueDate} onChange={e=>setDueDate(e.target.value)}/></label></div><div className="form-row"><label>Budget<input type="number" min="0" step="0.01" value={budget} onChange={e=>setBudget(e.target.value)}/></label><label>Currency<input maxLength={3} value={currency} onChange={e=>setCurrency(e.target.value.toUpperCase())}/></label></div><label>Assign to<select value={assigneeId} onChange={e=>setAssigneeId(e.target.value)}><option value="">Unassigned</option>{members.map(m=><option key={m.user.id} value={m.user.id}>{m.user.name}</option>)}</select></label><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setShowForm(false)}>Cancel</button><button className="btn primary" type="submit">Create project</button></div></form></div>}
 {selected&&<div className="modal-backdrop"><section className="record-modal project-detail-modal"><div className="modal-head"><div><div className="eyebrow">PROJECT DETAILS</div><h2>{selected.name}</h2></div><button className="icon" onClick={()=>setSelected(null)}><X/></button></div><p>{selected.description||'No description provided.'}</p><button className="btn secondary small" onClick={()=>setEditing(v=>!v)}>{editing?'Cancel edit':'Edit project details'}</button>{editing&&<form className="project-edit-form" onSubmit={saveEdit}><label>Project name<input required value={editName} onChange={e=>setEditName(e.target.value)}/></label><label>Description<textarea rows={3} value={editDescription} onChange={e=>setEditDescription(e.target.value)}/></label><div className="form-row"><label>Due date<input type="date" value={editDueDate} onChange={e=>setEditDueDate(e.target.value)}/></label><label>Budget<input type="number" min="0" step="0.01" value={editBudget} onChange={e=>setEditBudget(e.target.value)}/></label></div><label>Priority<select value={editPriority} onChange={e=>setEditPriority(e.target.value as Project['priority'])}><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>URGENT</option></select></label><label>Assign to<select value={editAssigneeId} onChange={e=>setEditAssigneeId(e.target.value)}><option value="">Unassigned</option>{members.map(m=><option key={m.user.id} value={m.user.id}>{m.user.name}</option>)}</select></label><label>Progress · {editProgress}%<input type="range" min="0" max="100" value={editProgress} onChange={e=>setEditProgress(Number(e.target.value))}/></label><button className="btn primary" type="submit">Save project</button></form>}<div className="settings-action"><span><b>Status</b><small>{selected.status.replace('_',' ')} · {selected.priority} priority</small></span><span>{selected.progress}% complete</span></div><div className="settings-action"><span><b>Budget</b><small>{selected.budget?`${selected.currency} ${Number(selected.budget).toLocaleString()}`:'No budget assigned'}</small></span><span>{selected.dueDate?new Date(selected.dueDate).toLocaleDateString():'No deadline'}</span></div><h3>Milestones</h3>{(selected as any).milestones?.map((m:any)=><div className="settings-action" key={m.id}><span><b>{m.title}</b><small>{m.dueDate?new Date(m.dueDate).toLocaleDateString():'No due date'}</small></span><span className="status">{m.completedAt?'Completed':'Pending'}</span>{!m.completedAt&&<button className="btn secondary small" onClick={()=>void completeMilestone(m.id)}>Complete</button>}</div>)}<form className="inline-form" onSubmit={addMilestone}><input value={milestone} onChange={e=>setMilestone(e.target.value)} placeholder="Add a milestone"/><button className="btn secondary" type="submit" disabled={!milestone.trim()}>Add</button></form><h3>Activity</h3>{(selected as any).activities?.slice(0,8).map((a:any)=><div className="dash-activity" key={a.id}><span className="activity-dot"/><div><b>{a.action.replaceAll('_',' ')}</b><small>{new Date(a.createdAt).toLocaleString()}</small></div></div>)}<div className="modal-actions"><button className="btn secondary" onClick={()=>void archive(selected)}>Archive</button><button className="btn secondary danger-action" onClick={()=>void remove(selected)}>Delete</button><button className="btn primary" onClick={()=>setSelected(null)}>Close</button></div></section></div>}</>;
}

function DataPage({kind,items,query,onAdd,onRemove,onStatus}:{kind:Dataset;items:RecordItem[];query:string;onAdd:()=>void;onRemove:(id:string)=>void;onStatus:(id:string,s:string)=>void}){
 const names:Record<string,[string,string,string]>={projects:['Projects','Plan, organize and track delivery.','project'],tasks:['Tasks','Keep priorities clear and work moving.','task'],customers:['Customers','Manage the contacts and relationships you add.','customer'],invoices:['Invoices','Create invoices and track their payment status.','invoice']};
 const [title,desc,singular]=names[kind];const filtered=items.filter(x=>(x.name+' '+x.detail+' '+x.status).toLowerCase().includes(query.toLowerCase()));
 if(kind==='tasks'||kind==='projects')return <><Heading eyebrow={`WORKSPACE / ${title.toUpperCase()}`} title={title} desc={desc} action={<button className="btn primary" onClick={onAdd}><Plus size={16}/> New {singular}</button>}/><div className="board-columns">{(kind==='tasks'?['To do','In progress','In review','Done']:['Planning','In progress','On track','Completed']).map(status=><section className="board-column" key={status}><div className="column-head"><span className="column-dot"/><b>{status}</b><i>{filtered.filter(x=>x.status===status).length}</i></div>{filtered.filter(x=>x.status===status).map(item=><article className="board-card" key={item.id}><div className="card-menu"><Status value={item.status}/><button className="icon" onClick={()=>onRemove(item.id)} title="Delete"><Trash2 size={14}/></button></div><b>{item.name}</b><p>{item.detail||'No details added.'}</p>{item.date&&<small><Clock3 size={12}/>{item.date}</small>}<select value={item.status} onChange={e=>onStatus(item.id,e.target.value)} aria-label="Change status">{(kind==='tasks'?['To do','In progress','In review','Done']:['Planning','In progress','On track','Completed']).map(s=><option key={s}>{s}</option>)}</select></article>)}<button className="add-inline" onClick={onAdd}><Plus size={14}/> Add {singular}</button></section>)}</div>{filtered.length===0&&<div className="panel board-empty"><Empty title={`No ${title.toLowerCase()} yet`} desc="Your board is empty. Add a real record to get started." action={`Add ${singular}`} onClick={onAdd}/></div>}</>;
 return <><Heading eyebrow={`WORKSPACE / ${title.toUpperCase()}`} title={title} desc={desc} action={<button className="btn primary" onClick={onAdd}><Plus size={16}/> New {singular}</button>}/><div className="table-toolbar"><span>{filtered.length} {filtered.length===1?'record':'records'}</span><span>Server-backed workspace data</span></div><div className="panel table-panel">{filtered.length?<table><thead><tr><th>{title.slice(0,-1)||title}</th><th>Details</th><th>{kind==='invoices'?'Amount':'Date added'}</th><th>Status</th><th/></tr></thead><tbody>{filtered.map(x=><tr key={x.id}><td><b>{x.name}</b></td><td>{x.detail||'—'}</td><td>{kind==='invoices'?money(x.amount||0):new Date(x.createdAt).toLocaleDateString()}</td><td><select className="status-select" value={x.status} onChange={e=>onStatus(x.id,e.target.value)}>{(kind==='invoices'?['Draft','Sent','Paid','Overdue']:['Lead','Active','Inactive']).map(s=><option key={s}>{s}</option>)}</select></td><td><button className="icon danger" onClick={()=>onRemove(x.id)} title="Delete record"><Trash2 size={15}/></button></td></tr>)}</tbody></table>:<Empty title={`No ${title.toLowerCase()} yet`} desc="No sample records are inserted. Add your own information to begin." action={`Add ${singular}`} onClick={onAdd}/>}</div></>;
}
export function RecordModal({kind,onClose,onSave}:{kind:Dataset;onClose:()=>void;onSave:(v:Omit<RecordItem,'id'|'createdAt'>)=>void}){
 const config:Record<string,{title:string;fields:string[];statuses:string[]}>={projects:{title:'New project',fields:['Project name','Description / client'],statuses:['Planning','In progress','On track','Completed']},tasks:{title:'New task',fields:['Task title','Description / project'],statuses:['To do','In progress','In review','Done']},customers:{title:'New customer',fields:['Customer name','Email / company / notes'],statuses:['Lead','Active','Inactive']},invoices:{title:'New invoice',fields:['Invoice number / title','Customer / description'],statuses:['Draft','Sent','Paid','Overdue']},events:{title:'New calendar event',fields:['Event title','Description'],statuses:['Scheduled','Done']}};
 const c=config[kind], [name,setName]=useState(''),[detail,setDetail]=useState(''),[status,setStatus]=useState(c.statuses[0]),[amount,setAmount]=useState(''),[date,setDate]=useState(new Date().toISOString().slice(0,10));
 const submit=(e:FormEvent)=>{e.preventDefault();onSave({name:name.trim(),detail:detail.trim(),status,...(kind==='invoices'?{amount:Number(amount)}:{}),date})};
 return <div className="modal-backdrop" onMouseDown={onClose}><form className="modal" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><button type="button" className="modal-close icon" onClick={onClose}><X/></button><div className="eyebrow">WORKSPACE RECORD</div><h2>{c.title}</h2><label>{c.fields[0]}<input autoFocus required value={name} onChange={e=>setName(e.target.value)} placeholder="Enter a name"/></label><label>{c.fields[1]}<textarea value={detail} onChange={e=>setDetail(e.target.value)} placeholder="Add useful details (optional)"/></label>{kind==='invoices'&&<label>Amount<input type="number" min="0" step="0.01" required value={amount} onChange={e=>setAmount(e.target.value)} placeholder="0.00"/></label>}<div className="form-pair"><label>Status<select value={status} onChange={e=>setStatus(e.target.value)}>{c.statuses.map(s=><option key={s}>{s}</option>)}</select></label><label>{kind==='tasks'||kind==='events'||kind==='invoices'?'Date':'Date added'}<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label></div><button className="btn primary full">Save {kind.slice(0,-1)}</button><small className="form-note">This record is saved locally in this browser.</small></form></div>;
}
function Analytics({data}:{data:Record<Dataset,RecordItem[]>}){
 const invoice=data.invoices,paid=invoice.filter(x=>x.status==='Paid'),sum=paid.reduce((a,x)=>a+(x.amount||0),0),outstanding=invoice.filter(x=>x.status==='Sent'||x.status==='Overdue').reduce((a,x)=>a+(x.amount||0),0);
 const bars=[{name:'Paid',value:paid.length},{name:'Sent',value:invoice.filter(x=>x.status==='Sent').length},{name:'Overdue',value:invoice.filter(x=>x.status==='Overdue').length},{name:'Draft',value:invoice.filter(x=>x.status==='Draft').length}];
 return <><Heading eyebrow="INSIGHTS" title="Analytics" desc="Calculated directly from your saved workspace records."/><div className="quick-grid"><Quick label="Collected revenue" value={money(sum)} icon={<Wallet/>} hint="Paid invoices only"/><Quick label="Outstanding" value={money(outstanding)} icon={<Receipt/>} hint="Sent and overdue invoices"/><Quick label="Projects" value={data.projects.length} icon={<FolderKanban/>} hint="All project records"/><Quick label="Tasks completed" value={data.tasks.filter(x=>x.status==='Done').length} icon={<Target/>} hint="Marked as done"/></div><section className="panel analytics-panel"><PanelHead title="Invoice status" sub="Number of invoices in each status"/>{invoice.length?<div className="chart tall"><ResponsiveContainer width="100%" height="100%"><BarChart data={bars}><CartesianGrid stroke="var(--line)" vertical={false} strokeDasharray="3 4"/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis allowDecimals={false} axisLine={false} tickLine={false}/><Tooltip/><Bar dataKey="value" fill="var(--accent)" radius={[7,7,0,0]}/></BarChart></ResponsiveContainer></div>:<Empty title="Not enough data to analyze" desc="Add invoices first. Charts and totals will be derived from your entries." action="Create invoice" onClick={()=>window.location.assign('/invoices')}/>}</section></>;
}
function CalendarPage({data,onAdd}:{data:Record<Dataset,RecordItem[]>;onAdd:(k:Dataset)=>void}){
 const items=[...data.events,...data.tasks.filter(t=>t.date).map(t=>({...t,status:t.status}))].sort((a,b)=>(a.date||'').localeCompare(b.date||''));
 return <><Heading eyebrow="PLANNING" title="Calendar" desc="Your dated tasks and events, in chronological order." action={<button className="btn primary" onClick={()=>onAdd('events')}><Plus size={16}/> Add event</button>}/><div className="panel calendar-panel">{items.length?items.map(x=><div className="calendar-row" key={x.id}><div className="calendar-date"><b>{x.date?new Date(x.date+'T12:00:00').getDate():'—'}</b><small>{x.date?new Date(x.date+'T12:00:00').toLocaleString(undefined,{month:'short'}):''}</small></div><div className="row-main"><b>{x.name}</b><small>{x.detail||'No details'}</small></div><Status value={x.status}/></div>):<Empty title="Your calendar is clear" desc="Add events or give tasks due dates. They will appear here." action="Add event" onClick={()=>onAdd('events')}/>}</div></>;
}
function AIPage({data,storageScope}:{data:Record<Dataset,RecordItem[]>;storageScope:string}){
 const [endpoint,setEndpoint]=useState(()=>readScopedStore(storageScope,'ai-endpoint',import.meta.env.VITE_AI_API_URL||'')),[prompt,setPrompt]=useState(''),[messages,setMessages]=useState<{role:string;content:string}[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const send=async(e:FormEvent)=>{e.preventDefault();if(!endpoint.trim()){setError('AI is not connected. Add a secure backend endpoint in Settings or VITE_AI_API_URL. No simulated answers are shown.');return}const q=prompt.trim();if(!q)return;setPrompt('');setError('');setMessages(m=>[...m,{role:'user',content:q}]);setBusy(true);try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,context:{projects:data.projects,tasks:data.tasks,customers:data.customers,invoices:data.invoices}})});if(!response.ok)throw new Error(`AI service returned ${response.status}.`);const result=await response.json();const answer=result.reply||result.answer||result.message;if(typeof answer!=='string'||!answer.trim())throw new Error('The AI service returned no readable answer.');setMessages(m=>[...m,{role:'assistant',content:answer}]);}catch(err){setError(err instanceof Error?err.message:'Could not reach the AI service.');}finally{setBusy(false)}};
 return <><Heading eyebrow="FLOWDESK INTELLIGENCE" title="AI Assistant" desc="Ask questions about your workspace or get help planning the next step."/><div className="ai-layout"><section className="panel ai-chat"><div className="ai-intro"><span className="ai-mark"><BrainCircuit size={23}/></span><h2>Your workspace copilot</h2><p>Responses come from your connected AI service. This app does not invent replies or include a bundled demo bot.</p></div><div className="messages">{messages.map((m,i)=><div className={'message '+m.role} key={i}><b>{m.role==='user'?'You':'FlowDesk AI'}</b><p>{m.content}</p></div>)}{busy&&<div className="message assistant"><b>FlowDesk AI</b><p>Waiting for the AI service…</p></div>}</div>{error&&<div className="error-note">{error}</div>}<form className="ai-compose" onSubmit={send}><textarea value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Ask about your projects, tasks, customers or invoices…" rows={2}/><button className="btn primary" disabled={busy||!prompt.trim()}><Send size={16}/> Send</button></form><small className="form-note">Workspace context is sent to the endpoint you configure. Do not include sensitive information unless your provider is approved for it.</small></section><aside className="panel ai-side"><h3>Workspace context</h3><p>Current record counts available to the assistant.</p>{[['Projects',data.projects.length],['Tasks',data.tasks.length],['Customers',data.customers.length],['Invoices',data.invoices.length]].map(([n,v])=><div className="context-row" key={n}><span>{n}</span><b>{v}</b></div>)}<div className="ai-config"><b>Connection</b><input value={endpoint} onChange={e=>setEndpoint(e.target.value)} placeholder="https://your-server/ai/chat"/><small>Use a server-side proxy. Never put provider API keys in frontend code.</small></div></aside></div></>;
}
function SettingsPage({storageScope,workspaceId,workspaceRole,owner,setOwner,workspace,setWorkspace,setNotice,setDark,onLogout}:{storageScope:string;workspaceId:string;workspaceRole:'OWNER'|'ADMIN'|'MANAGER'|'MEMBER'|'VIEWER';owner:string;setOwner:(v:string)=>void;workspace:string;setWorkspace:(v:string)=>void;setNotice:(v:string)=>void;setDark:(v:boolean)=>void;onLogout:()=>void}){
 const [name,setName]=useState(owner),[space,setSpace]=useState(workspace),[theme,setTheme]=useState(document.documentElement.dataset.theme||'light');
 const [tab,setTab]=useState('Profile'),[settingsError,setSettingsError]=useState('');
 const [spaceDescription,setSpaceDescription]=useState(''),[spaceLogoUrl,setSpaceLogoUrl]=useState(''),[originalSpaceDescription,setOriginalSpaceDescription]=useState(''),[originalSpaceLogoUrl,setOriginalSpaceLogoUrl]=useState('');
 useEffect(()=>{workspaceService.get(workspaceId).then(r=>{setSpaceDescription(r.workspace.description||'');setSpaceLogoUrl(r.workspace.logoUrl||'');setOriginalSpaceDescription(r.workspace.description||'');setOriginalSpaceLogoUrl(r.workspace.logoUrl||'')}).catch(e=>setSettingsError(e instanceof Error?e.message:'Workspace settings could not be loaded.'));},[workspaceId]);
 const tabs=['Profile','Team','Security','Appearance','Preferences','AI connection','Data & privacy','Account'];
 const [teamMembers,setTeamMembers]=useState<Array<{id:string;role:'OWNER'|'ADMIN'|'MANAGER'|'MEMBER'|'VIEWER';user:{id:string;name:string;email:string;avatarUrl?:string|null}}>>([]),[inviteEmail,setInviteEmail]=useState(''),[inviteRole,setInviteRole]=useState<'ADMIN'|'MANAGER'|'MEMBER'|'VIEWER'>('MEMBER'),[inviteToken,setInviteToken]=useState(''),[pendingInvitations,setPendingInvitations]=useState<Array<{id:string;email:string;role:string;expiresAt:string}>>([]);
 const refreshTeam=()=>{workspaceService.members(workspaceId).then(r=>setTeamMembers(r.members)).catch(e=>setSettingsError(e instanceof Error?e.message:'Workspace members could not be loaded.'));workspaceService.invitations(workspaceId).then(r=>setPendingInvitations(r.invitations)).catch(e=>{if(workspaceRole==='OWNER'||workspaceRole==='ADMIN')setSettingsError(e instanceof Error?e.message:'Workspace invitations could not be loaded.')});};
 useEffect(()=>{refreshTeam();},[workspaceId]);
 const inviteMember=async()=>{try{const result=await workspaceService.invite(workspaceId,inviteEmail,inviteRole);setInviteToken(result.acceptanceToken||'');setInviteEmail('');refreshTeam();setNotice('Invitation created.');}catch(e){setNotice(e instanceof Error?e.message:'Invitation could not be created.')}};
 const [twoFactor,setTwoFactor]=useState(false),[totpSecret,setTotpSecret]=useState(''),[totpCode,setTotpCode]=useState(''),[sessions,setSessions]=useState<Array<{id:string;createdAt:string;expiresAt:string;userAgent:string|null;ipAddress:string|null}>>([]),[securityMessage,setSecurityMessage]=useState(''),[recoveryCodes,setRecoveryCodes]=useState<string[]>([]);
 useEffect(()=>{authService.me().then(r=>setTwoFactor(r.user.twoFactorEnabled)).catch(()=>{});authService.sessions().then(r=>setSessions(r.sessions)).catch(()=>{});},[]);
 const setup2fa=async()=>{try{const r=await authService.setup2fa();setTotpSecret(r.secret);setSecurityMessage('Add this secret to an authenticator app, then enter its current six-digit code.')}catch(e){setSecurityMessage(e instanceof Error?e.message:'Could not start two-factor setup.')}};
 const enable2fa=async()=>{try{const r=await authService.enable2fa(totpCode);setTwoFactor(true);setTotpSecret('');setTotpCode('');setRecoveryCodes(r.recoveryCodes);setSecurityMessage(r.message)}catch(e){setSecurityMessage(e instanceof Error?e.message:'Could not enable two-factor authentication.')}};
 const disable2fa=async()=>{try{await authService.disable2fa(totpCode);setTwoFactor(false);setTotpCode('');setSecurityMessage('Two-factor authentication is disabled.')}catch(e){setSecurityMessage(e instanceof Error?e.message:'Could not disable two-factor authentication.')}};
 const [prefs,setPrefs]=useState<any>({theme:'system',locale:'en',dateFormat:'DD/MM/YYYY',weekStartsOn:1,compactMode:false,emailDigest:'daily',productUpdates:false});useEffect(()=>{preferenceService.get().then(r=>{setPrefs(r.preferences);if(r.preferences.theme==='light'||r.preferences.theme==='dark'){setTheme(r.preferences.theme);setDark(r.preferences.theme==='dark')}}).catch(()=>{})},[]);
 const [avatarUrl,setAvatarUrl]=useState(''),[bio,setBio]=useState(''),[timezone,setTimezone]=useState('');useEffect(()=>{profileService.get().then(r=>{setAvatarUrl(r.user.avatarUrl||'');setBio(r.user.bio||'');setTimezone(r.user.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone)}).catch(()=>{});},[]);const save=async()=>{try{setSettingsError('');const workspaceChanged=(space.trim()||workspace)!==workspace||spaceDescription.trim()!==originalSpaceDescription||spaceLogoUrl.trim()!==originalSpaceLogoUrl;if(workspaceChanged&&workspaceRole!=='OWNER'&&workspaceRole!=='ADMIN')throw new Error('Your workspace role does not allow workspace settings changes.');await profileService.update({name:name.trim(),avatarUrl:avatarUrl.trim()||null,bio:bio.trim()||null,timezone:timezone.trim()||null});if(workspaceRole==='OWNER'||workspaceRole==='ADMIN'){await workspaceService.update(workspaceId,{name:space.trim()||workspace,description:spaceDescription.trim()||null,logoUrl:spaceLogoUrl.trim()||null});setOriginalSpaceDescription(spaceDescription.trim());setOriginalSpaceLogoUrl(spaceLogoUrl.trim());}else if(workspaceChanged){throw new Error('Your profile was saved, but your workspace role does not allow workspace settings changes.');}await preferenceService.update(prefs);setOwner(name.trim());setWorkspace(space.trim()||workspace);setNotice('Profile, workspace and personal preferences saved to your FlowDesk account.')}catch(e){setSettingsError(e instanceof Error?e.message:'Settings could not be saved.');setNotice(e instanceof Error?e.message:'Settings could not be saved.')}};
 const exportData=()=>{const payload={theme:readScopedStore(storageScope,'dark',false)?'dark':'light'};const blob=new Blob([JSON.stringify({product:'FlowDesk',exportedAt:new Date().toISOString(),devicePreferences:payload},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='flowdesk-workspace-backup.json';a.click();URL.revokeObjectURL(url);};
 return <><Heading eyebrow="PREFERENCES" title="Settings" desc="Configure your workspace, appearance, AI connection and local data."/>{settingsError&&<div className="error-note">{settingsError}</div>}<div className="settings-grid"><aside className="settings-tabs">{tabs.map(t=><button key={t} className={tab===t?'selected':''} onClick={()=>setTab(t)}>{t}</button>)}</aside><section className="panel settings-panel">
 {tab==='Profile'&&<><h3>Workspace profile</h3><p>Control the name and identity shown throughout this browser workspace.</p><label>Your display name<input value={name} onChange={e=>setName(e.target.value)} placeholder="Enter your name"/></label><label>Profile picture URL<input value={avatarUrl} onChange={e=>setAvatarUrl(e.target.value)} placeholder="https://…"/></label><label>About you<textarea value={bio} onChange={e=>setBio(e.target.value)} rows={3} placeholder="A short profile bio"/></label><label>Timezone<input value={timezone} onChange={e=>setTimezone(e.target.value)} placeholder="Africa/Lagos"/></label><label>Workspace name<input value={space} onChange={e=>setSpace(e.target.value)} placeholder="My workspace"/></label><label>Workspace description<textarea rows={2} value={spaceDescription} onChange={e=>setSpaceDescription(e.target.value)} placeholder="What is this workspace for?"/></label><label>Workspace logo URL<input value={spaceLogoUrl} onChange={e=>setSpaceLogoUrl(e.target.value)} placeholder="https://…"/></label><div className="settings-info"><Activity size={17}/><span><b>Server-managed identity</b><small>Your profile and workspace name are saved through the authenticated FlowDesk API. Profile images currently use an HTTPS image URL; profile-image file uploads are not supported by this account API.</small></span></div></>}
 {tab==='Team'&&<><h3>Workspace members</h3><p>Manage membership and assign workspace roles. Only workspace owners can change roles; owners and admins can invite members.</p>{(workspaceRole==='OWNER'||workspaceRole==='ADMIN')&&<><div className="settings-action"><label style={{flex:1}}>Invite by email<input type="email" value={inviteEmail} onChange={e=>setInviteEmail(e.target.value)} placeholder="teammate@example.com"/></label><label>Role<select value={inviteRole} onChange={e=>setInviteRole(e.target.value as typeof inviteRole)}><option value="MEMBER">Member</option><option value="MANAGER">Manager</option><option value="ADMIN">Admin</option><option value="VIEWER">Viewer</option></select></label><button className="btn primary" onClick={inviteMember} disabled={!inviteEmail.trim()}>Create invite</button></div>{inviteToken&&<div className="settings-info"><span><b>Invitation acceptance token</b><small>Share privately with the invited user. It expires after seven days. {inviteToken}</small><button className="btn secondary small" onClick={()=>navigator.clipboard.writeText(inviteToken)}>Copy token</button></span></div>}<h3 style={{marginTop:24}}>Pending invitations</h3>{pendingInvitations.map(inv=><div className="settings-action" key={inv.id}><span><b>{inv.email}</b><small>{inv.role} · Expires {new Date(inv.expiresAt).toLocaleDateString()}</small></span><button className="btn secondary small" onClick={async()=>{try{await workspaceService.revokeInvitation(workspaceId,inv.id);setPendingInvitations(v=>v.filter(x=>x.id!==inv.id));}catch(e){setNotice(e instanceof Error?e.message:'Invitation could not be revoked.')}}}>Revoke</button></div>)}</>}{teamMembers.map(m=><div className="settings-action" key={m.id}><span><b>{m.user.name}</b><small>{m.user.email} · Joined {new Date().toLocaleDateString()}</small></span><span className={'status '+m.role.toLowerCase()}>{m.role}</span>{workspaceRole==='OWNER'&&m.role!=='OWNER'&&<select aria-label={`Role for ${m.user.name}`} defaultValue={m.role} onChange={async e=>{try{await workspaceService.setRole(workspaceId,m.user.id,e.target.value as 'ADMIN'|'MANAGER'|'MEMBER'|'VIEWER');setTeamMembers(v=>v.map(x=>x.id===m.id?{...x,role:e.target.value as typeof x.role}:x));}catch(err){setNotice(err instanceof Error?err.message:'Role could not be changed.')}}}><option value="ADMIN">Admin</option><option value="MANAGER">Manager</option><option value="MEMBER">Member</option><option value="VIEWER">Viewer</option></select>}{(workspaceRole==='OWNER'||workspaceRole==='ADMIN')&&m.role!=='OWNER'&&(workspaceRole==='OWNER'||m.role!=='ADMIN')&&<button className="btn secondary small" onClick={async()=>{try{await workspaceService.remove(workspaceId,m.user.id);setTeamMembers(v=>v.filter(x=>x.id!==m.id));}catch(err){setNotice(err instanceof Error?err.message:'Member could not be removed.')}}}>Remove</button>}</div>)}</>}
 {tab==='Security'&&<><h3>Account security</h3><p>Protect your account and review devices with an active session.</p><div className="settings-action"><span><b>Two-factor authentication</b><small>{twoFactor?'Enabled — authenticator code required at sign-in.':'Disabled — add an authenticator app for additional protection.'}</small></span><span className={'status '+(twoFactor?'completed':'')}>{twoFactor?'Enabled':'Disabled'}</span></div>{!twoFactor&&!totpSecret&&<button className="btn secondary" onClick={setup2fa}>Set up authenticator</button>}{totpSecret&&<div className="settings-info"><span><b>Manual setup key</b><small>{totpSecret}</small></span></div>}{(totpSecret||twoFactor)&&<label>Authenticator code<input inputMode="numeric" value={totpCode} onChange={e=>setTotpCode(e.target.value)} placeholder="6-digit code"/></label>}{totpSecret&&<button className="btn primary" onClick={enable2fa}>Verify and enable</button>}{twoFactor&&<button className="btn secondary danger-action" onClick={disable2fa}>Disable two-factor</button>}{securityMessage&&<div className="settings-info">{securityMessage}</div>}{recoveryCodes.length>0&&<div className="settings-info"><span><b>Recovery codes — save these now</b><small>{recoveryCodes.join(' · ')}</small><button className="btn secondary small" onClick={()=>navigator.clipboard.writeText(recoveryCodes.join('\n'))}>Copy recovery codes</button></span></div>}<h3 style={{marginTop:28}}>Active sessions</h3>{sessions.map(s=><div className="settings-action" key={s.id}><span><b>{s.userAgent||'Unknown device'}</b><small>{s.ipAddress||'IP unavailable'} · Expires {new Date(s.expiresAt).toLocaleString()}</small></span><button className="btn secondary small" onClick={async()=>{await authService.revokeSession(s.id);setSessions(v=>v.filter(x=>x.id!==s.id))}}>Revoke</button></div>)}</> }
 {tab==='Appearance'&&<><h3>Appearance</h3><p>Choose how FlowDesk looks on this device.</p><div className="theme-choices"><button className={theme==='light'?'chosen':''} onClick={()=>{setTheme('light');setPrefs((v:any)=>({...v,theme:'light'}));setDark(false)}}><Sun size={17}/> Light mode</button><button className={theme==='dark'?'chosen':''} onClick={()=>{setTheme('dark');setPrefs((v:any)=>({...v,theme:'dark'}));setDark(true)}}><Moon size={17}/> Dark mode</button></div><div className="settings-info"><span className="accent-swatch"/><span><b>FlowDesk orange</b><small>Orange is the application accent across buttons, highlights and charts.</small></span></div></>}
 {tab==='Preferences'&&<><h3>Personal preferences</h3><p>These settings are saved to your FlowDesk account and follow you across devices.</p><label>Language<select value={prefs.locale} onChange={e=>setPrefs((v:any)=>({...v,locale:e.target.value}))}><option value="en">English</option><option value="en-GB">English (UK)</option><option value="en-US">English (US)</option></select></label><label>Date format<select value={prefs.dateFormat} onChange={e=>setPrefs((v:any)=>({...v,dateFormat:e.target.value}))}><option>DD/MM/YYYY</option><option>MM/DD/YYYY</option><option>YYYY-MM-DD</option></select></label><label>Week starts on<select value={prefs.weekStartsOn} onChange={e=>setPrefs((v:any)=>({...v,weekStartsOn:Number(e.target.value)}))}><option value={1}>Monday</option><option value={0}>Sunday</option></select></label><label>Email digest<select value={prefs.emailDigest} onChange={e=>setPrefs((v:any)=>({...v,emailDigest:e.target.value}))}><option value="off">Off</option><option value="daily">Daily</option><option value="weekly">Weekly</option></select></label><label className="settings-action"><span><b>Compact layout</b></span><input type="checkbox" checked={prefs.compactMode} onChange={e=>setPrefs((v:any)=>({...v,compactMode:e.target.checked}))}/></label><label className="settings-action"><span><b>Product updates</b></span><input type="checkbox" checked={prefs.productUpdates} onChange={e=>setPrefs((v:any)=>({...v,productUpdates:e.target.checked}))}/></label></>}
 {tab==='AI connection'&&<><h3>FlowDesk AI provider</h3><p>AI requests are handled by the FlowDesk backend. Provider credentials are configured by the platform operator on the server and are never stored in this browser.</p><div className="settings-info"><Sparkles size={17}/><span><b>Server-side configuration</b><small>Set AI_PROVIDER, AI_BASE_URL, AI_MODEL and AI_API_KEY in the backend environment. Restart the API after changing provider settings. Open the AI Assistant page to start a workspace-aware conversation.</small></span></div></>}
 {tab==='Data & privacy'&&<><h3>Your data</h3><p>Export a copy of browser-local preferences and legacy cached values.</p><div className="settings-action"><span><b>Export workspace backup</b><small>Download browser-local preferences only. Server-backed projects, tasks, customers, invoices and files are not included.</small></span><button className="btn secondary" onClick={exportData}>Export data</button></div><div className="settings-action"><span><b>Local storage</b><small>Business records are server-managed. This export contains device preferences only, not a complete workspace backup.</small></span><span className="status">On this device</span></div></>}
 {tab==='Account'&&<><h3>Account session</h3><p>This account is authenticated by the FlowDesk server.</p><div className="settings-info"><Users size={17}/><span><b>{owner||'Workspace user'}</b><small>Your secure server-managed session is active. Configure two-factor authentication for additional protection.</small></span></div><button className="btn secondary danger-action" onClick={onLogout}><LogOut size={15}/> Sign out</button></>}
 <div className="settings-footer"><span>Profile and workspace settings are saved to your account.</span><button className="btn primary" onClick={save}>Save changes</button></div>
 </section></div></>;
}
